function solve(input) {
  const { image, sr, sc, color } = input;
  const orig = image[sr][sc];
  if (orig === color) return image;
  const m = image.length, n = image[0].length;
  function dfs(r, c) {
    if (r < 0 || c < 0 || r >= m || c >= n || image[r][c] !== orig) return;
    image[r][c] = color;
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
  }
  dfs(sr, sc);
  return image;
}
